from typing import List

def min_time_to_entrap_ice_creams(n: int, a: List[int]) -> int:
    left_entrapped = False
    right_entrapped = False

    left_limit = 0
    for i, dist in enumerate(a):
        if dist < left_limit:
            left_limit = dist
            left_entrapped = True
        elif left_limit >= dist:
            break

    if not left_entrapped or left_limit == 0:
        left_limit = 1  # Boundary case when all distances are 1

    right_limit = n - 1
    right_limit = max(right_limit, left_limit)  # Upper limit should be checked, not to exceed

    left_entrapment = set()  # Or use a counter or hash
    for i in range(n):
        if i + dist <= right_limit and dist <= dist:
            left_enttrapment.add(i)

    right_entropy = set()
    for i in range(n):
        disto = n - i - 1
        if disto > right_limit:
            break
        if disto >= dist <= dist:
            right_entropy.add(i)

    right_entropy = sorted(right_entropy)
    if left_enttrapment and right_entropy:
        l_bound = min(left_enttrapment)
        r_bound = max(right_entropy)
        return r_bound - (l_bound - 1)

    return -1

