from collections import defaultdict
import heapq

def dijkstra(n, roads, profit):
    graph = defaultdict(list)
    for a, b, c in roads:
        graph[a].append((b, c))
        graph[b].append((a, -c))  # Negate profit to use Dijkstra

    distances = {node: float('inf') for node in range(1, n+1)}
    distances[1] = 0
    pq = [(0, 1)]  # (distance, node)

    while pq:
        current_distance, node = heapq.heappop(pq)

        if current_distance > distances[node]:
            continue

        for neighbor, profit_gain in graph[node]:
            profit_loss = current_distance + profit_gain
            if profit_loss < distances[neighbor]:
                distances[neighbor] = profit_loss
                heapq.heappush(pq, (profit_loss, neighbor))
    return distances

def calculate_gain(n, query, root):
    distances = dijkstra(n, [(root, xi, yi) for xi, yi, _ in query], -query[0][2])
    if query[0][0] not in distances or query[0][1] != root:
        return -distances[query[0][1]]
    return str(distances[query[1]])

