        visited[num_contacts] = True
        distances[num_contacts] = 0
        path = []

        while True:
            min_dist = float('inf')
            min_node = None

            for node in range(1, num_contacts + 1):
                if not visited[node] and distances[node] < min_dist:
                    min_dist = distances[node]
                    min_node = node

            if min_node is None:
                break

