import sys

def to_rpn(expression):
    l_list = expression.replace("x", "1").replace("y", "2").replace("z", "3").replace("!", "~").split()
    stack = []
    output = []
    for item in l_list:
        if item.isdigit():
            output.append(item)
        else:
            if item == '~':
                output.append('~' + stack.pop())
            elif item == '|':
                while stack and stack[-1] != '&':
                    output.append(stack.pop())
                stack.pop()
                stack.append(item)
            elif item == '&':
                while stack and stack[-1] != '|' and stack[-1] != '!':
                    output.append(stack.pop())
                stack.pop()
                stack.append(item)
            elif item == '(':
                stack.append(item)
            elif item == ')':
                while stack:
                    oper = stack.pop()
                    if oper != '(':
                        output.append(oper)
    while stack:
        output.append(stack.pop())

    return output

def rpn_to_expression(rpn_expression):
    exp = ''
    len_db = {'!':1, '&':2, '|':3}
    dd = {1:'1', 2:'x', 3:'y', 4:'z', 5:'&', 6:'|'}
    expression = ['~']
    for i in range(len(rpn_expression)):
        if len(rpn_expression[i]) == 2 and rpn_expression[i][0] == '&':
            expression.append(rpn_expression[i][1])
        elif len(rpn_expression[i]) == 3 and rpn_expression[i][0] == '|':
            expression.append(rpn_expression[i][1])
        elif len(rpn_expression[i]) == 3 and rpn_expression[i][0] == '!':
            expression.append(rpn_expression[i][1])
        else:
            expression.append(dd[int(rpn_expression[i])])

    for i in range(len_db[expression[1]]):
        if len_db[expression[2]] == 1:
            exp += expression[2]
        else:
            exp += expression[2]
            exp += expression[3]
    return exp

