from collections import defaultdict, deque

def max_jills_toys(n, m):
    tree = defaultdict(lambda: [])
    for _ in range(m):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)

    island_count = 0
    dist = [-1] * (n + 1)
    dist[1] = 0
    for node in range(1, n + 1):
        if dist[node] > 0 and node not in tree:
            continue
        for neighbor in tree[node]:
            if dist[node] < dist[neighbor] + 1:
                dist[neighbor] = dist[node] + 1
        island_count += 1

    # Floyd-Warshall to find longest path length in each island
    for i in range(n):
        queue = deque([(i, 0)])
        while queue:
            node, length = queue.popleft()
            for neighbor in tree[node]:
                if dist[neighbor] > length + 1:
                    queue.append((neighbor, length + 1))
                    dist[neighbor] = length + 1

    # Sasha's path length in cactus
    sasha_toys = sum(node in tree and dist[node] for node in range(1, n+1))
    return dist, sasha_toys

