def calculate_expected_value(n, m, k):
    fact = [1] * (m + 2)
    for i in range(1, m + 1):
        fact[i] = fact[i-1] * i % 998244353

    inverse_fact = [1] * (m + 2)
    for i in range(m, 0, -1):
        inverse_fact[i] = pow(fact[i], m - 2, 998244353)

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0] = [1] * (m + 1)

    mod = 998244353
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(0, j + 1):
                if i > 1:
                    dp[i][j] = (dp[i][j] + pow(j, k, mod) * (-dp[i-1][j - k]) * inverse_fact[j - k] % mod) * inverse_fact[j] % mod
                else:
                    dp[i][j] = pow(j, k, mod) * pow(inverse_fact[j], k - 1, mod) % mod

