def replace_zeros_with_largest_ones(a, count_naughts, index_to_index_map, in_order_map):
    n = len(a)
    new_a = [float('-inf') if i % 2 == 0 else a[i] for i in range(n)]
    new_index_map = defaultdict(lambda: 0)
    largest_lones_index = -1
    sorted_indices = sorted(in_order_map.values())

    for i, index in enumerate(sorted_indices):
        if new_index_map[sorted_indices[0]] > i:
            largest_lones_index = sorted_indices[0]
        k = count_naughts[i]

        index_to_index_map[k].add(i)  # store index
        new_index_map[sorted_indices[k]] = i
        new_a[i] = k
        if i == n - 1 or a[i] != a[i + 1]:
            if k != new_a[i + 1]:
                largest_lones_index = i

    right_to_index_map = defaultdict(lambda: sorted_indices[-1])
    for j in reversed(range(n)):
        if new_index_map[sorted_indices[len(sorted_indices) - 1]] < j:
            largest_lones_index = sorted_indices[-1]
        k = count_naughts[j]

        index_to_index_map[k].add(j - 1)  # store index
        new_index_map[sorted_indices[k]] = j - 1
        new_a[j] = k
        if j == 0 or a[j] != a[j - 1]:
            if k != new_a[j - 1]:
                largest_lones_index = j

    new_a[closest_index(new_a, new_index_map, largest_lones_index, n)] = n
    if largest_lones_index == -1:
        return new_a

    for i, j in index_to_index_map.items():
        if i != 0 and (i - 1 in j or i + 1 in j):
            sorted_indices.remove(i)
            index_to_index_map.pop(i)
            largest_lones_index = -1

    for i in reversed(range(closest_index(new_a, new_index_map, largest_lones_index, n) + 2, n)):
        if new_a[i] == inf:
            new_a[i] = n

    for i in range(closest_index(new_a, new_index_map, largest_lones_index, n) - 2, -1, -1):
        if new_a[i] == n:
            new_a[i] = n - 1
    return new_a


def inf(n):
    if n == 1:
        return []
    elif n == 2:
        return [1, 2]
    else:
        return [-1]


def closest_index(a, new_index_map, largest_lones_index, n):
    l, r = 0, len(a) - 1
    answer = n
    l_ptr = l
    r_ptr = r
    prev_l = r_ptr
    closest_index = inf(n)

    while l < r:
        mid = l + (r - l) // 2

        if a[prev_l] <= a[mid]:
            # Need right biggest
            answer = min(answer, 2 * mid - prev_l)
            r = mid
        else:
            # Need left biggest
            l = mid + 1
        prev_l = l if a[prev_l] <= a[r] else r_ptr

    while l < r and new_index_map[r] >= answer:
        if l > 0 and new_index_map[l] < answer:
            answer = bisect_left(new_index_map, new_index_map[l]) - 1
            l = answer
        else:
            answer = bisect_right(new_index_map, answer)
            r = answer - 1

    return closest_index


