def min_entrapment_time(n, distances):
    if n < 2:
        return -1

    _sum, total, pre_sum, ans, mid = sum(distances), 0, [0] * (n+2), 1, n // 2

    for i in range(1, mid):
        for d in distances:
            _sum, pre_sum = _sum - i, pre_sum - i
            if _sum + d <= n and ( i * i + _sum ) <= total:
                total += _sum + d
                total -= pre_sum - i + ( (_sum + d) - _sum + pre_sum ) % (i + 2) // i
                if total <= 2 * pre_sum:
                    ans = max(ans, i * 2)
            else:
                break

    return ans + (binary_search(n, mid, total) != -1 and distance(total) == 2 * total) - 1

def distance(s):
    funice = [i for i in range(1, s + 1)]
    dif = abs(funice[0] - funice[1])
    for i in range(1, len(funice) - 2):
        dif = min(dif, abs(funice[i-1] - funice[i + 1]))
    return dif / 2 

def binary_search(n, mid, total):
    left = 0
    right = mid + 1
    while left <= right:
        mid = (left + right) // 2
        tmp = total + (mid - 1) * (mid - 1)
        if distance(tmp) < right - mid + 1:
            left = mid + 1
        else:
            right = mid - 1

    return -1 if left - right > mid - mid else left
