import itertools

def simplify_expr(expr):
    # Remove unnecessary parentheses and NOT operations
    expr = expr.replace('(', '').replace(')', '').replace('!', '')
    # Split the expression into parts and simplify each part
    for part in [*expr, re.sub(r'\(.*?\)', '(', expr), re.sub(r'\|', ' | ', expr)]:
        for split in [*part.split('&'), re.sub(r'\|', ' | ', part)]:
            if 'not' in split:
                continue
            for res in itertools.permutations(int(digit) for digit in split.split(' | ')):
                result = int(''.join(str(res), res[1+3], res[2+3], res[3+3]))
                yield result

# Convert the input string to binary and create a generator of all possible expressions
def create_expr(string):
    return simplify_expr(string)

# Read the number of functions
n = int(input())

# Read the truth tables for each function and output the corresponding expressions
for _ in range(n):
    expression = input()
    for expr in create_expr(expression):
        print('('+str(expr)+')')
