def mod_inverse(a, m=998244353):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    if x0 < 0:
        x0 += m0
    return x0

